create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public;
create table public.colleges(id uuid primary key default gen_random_uuid(), name text not null, domains text[] not null, downvotes_enabled boolean not null default false, keyword_filters text[] not null default '{}', ai_enabled boolean not null default false, created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users on delete cascade, college_id uuid not null references colleges, display_name text not null default 'Student' check(length(display_name) between 2 and 60), branch text not null default '', graduation_year int not null default 2027, interests text[] not null default '{}', avatar_path text, bio text not null default '' check(length(bio)<=500), role text not null default 'student' check(role in ('student','moderator','admin','alumni','club_head')), reputation int not null default 0, consented_at timestamptz, sponsor_consent boolean not null default false, settings jsonb not null default '{}', created_at timestamptz not null default now(), unique(id,college_id));
create function private.college() returns uuid language sql stable security definer set search_path='' as $$ select college_id from public.profiles where id=auth.uid() $$;
create function private.staff() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select role in ('moderator','admin') from public.profiles where id=auth.uid()),false)$$;
create function private.admin() returns boolean language sql stable security definer set search_path='' as $$select coalesce((select role='admin' from public.profiles where id=auth.uid()),false)$$;
create table public.sanctions(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,user_id uuid not null,kind text not null check(kind in ('warn','mute','ban')),expires_at timestamptz,reason text not null,created_at timestamptz not null default now(),foreign key(user_id,college_id) references profiles(id,college_id) on delete cascade);
create function private.active() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.consented_at is not null) and not exists(select 1 from public.sanctions where user_id=auth.uid() and kind in ('ban','mute') and (expires_at is null or expires_at>now()))$$;
create function public.allowed_college(email text) returns table(id uuid,name text) language sql stable security definer set search_path='' as $$select c.id,c.name from public.colleges c where lower(split_part(trim(email),'@',2))=any(c.domains)$$;
create function private.provision_profile() returns trigger language plpgsql security definer set search_path='' as $$declare cid uuid;begin
if new.email_confirmed_at is null then return new;end if;
select id into cid from public.colleges where lower(split_part(new.email,'@',2))=any(domains) limit 1;
if cid is null then raise exception 'College email domain is not allowed';end if;
insert into public.profiles(id,college_id) values(new.id,cid) on conflict(id) do nothing;return new;end$$;
create trigger verified_profile after insert or update of email_confirmed_at on auth.users for each row execute function private.provision_profile();
create function public.update_my_profile(input jsonb) returns void language plpgsql security definer set search_path='' as $$begin
if auth.uid() is null then raise exception 'Authentication required';end if;
update public.profiles set display_name=left(input->>'display_name',60),branch=left(input->>'branch',60),graduation_year=(input->>'graduation_year')::int,bio=left(coalesce(input->>'bio',''),500),interests=coalesce(array(select jsonb_array_elements_text(input->'interests')),'{}'),consented_at=coalesce(consented_at,now()) where id=auth.uid();end$$;
create table public.communities(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,name text not null check(length(name) between 2 and 80),description text not null default '',rules text not null default '',category text not null default 'General',created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id));
create table public.memberships(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,community_id uuid not null,role text not null default 'member' check(role='member'),created_at timestamptz not null default now(),unique(owner_id,community_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,foreign key(community_id,college_id) references communities(id,college_id) on delete cascade);
create table public.posts(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,community_id uuid not null,title text not null check(length(title) between 3 and 180),body text not null check(length(body) between 1 and 10000),flair text not null check(flair in ('Doubt','Notes','Experience','Opinion')),anonymous boolean not null default false,kind text not null default 'text' check(kind in ('text','image','poll')),image_path text,score int not null default 0,pinned boolean not null default false,official boolean not null default false,unverified boolean not null default false,deleted_at timestamptz,created_at timestamptz not null default now(),search tsvector generated always as(to_tsvector('english',title||' '||body)) stored,unique(id,college_id),foreign key(community_id,college_id) references communities(id,college_id));
create index posts_search on posts using gin(search);
create index posts_cursor on posts(college_id,created_at desc,id desc);
create table private.post_authors(post_id uuid primary key references public.posts on delete cascade,user_id uuid not null references public.profiles on delete cascade);
create table public.comments(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,post_id uuid not null,parent_id uuid,body text not null check(length(body) between 1 and 10000),deleted_at timestamptz,created_at timestamptz not null default now(),unique(id,post_id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,foreign key(post_id,college_id) references posts(id,college_id) on delete cascade,foreign key(parent_id,post_id,college_id) references comments(id,post_id,college_id));
create table public.votes(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,post_id uuid not null,value int not null check(value in (-1,1)),created_at timestamptz not null default now(),unique(owner_id,post_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,foreign key(post_id,college_id) references posts(id,college_id) on delete cascade);
create table public.polls(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,post_id uuid not null,question text not null,options jsonb not null check(jsonb_array_length(options) between 2 and 8),closes_at timestamptz,created_at timestamptz not null default now(),foreign key(owner_id,college_id) references profiles(id,college_id),foreign key(post_id,college_id) references posts(id,college_id) on delete cascade,unique(id,college_id));
create table public.poll_responses(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,poll_id uuid not null,option_index int not null check(option_index between 0 and 7),created_at timestamptz not null default now(),unique(owner_id,poll_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,foreign key(poll_id,college_id) references polls(id,college_id));
create table public.notes(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null default '',branch text not null,semester int not null check(semester between 1 and 12),subject text not null,file_path text not null,kind text not null default 'note' check(kind in ('note','paper')),accepted boolean not null default false);
create table public.reviews(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,subject text not null,teaching int not null check(teaching between 1 and 5),difficulty int not null check(difficulty between 1 and 5),grading int not null check(grading between 1 and 5),approved boolean not null default false);
create table public.clubs(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null default '',verified boolean not null default false);
create table public.events(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null default '',starts_at timestamptz not null,ends_at timestamptz not null,location text not null,club_id uuid,price_paise int not null default 0 check(price_paise>=0),fest boolean not null default false,foreign key(club_id,college_id) references clubs(id,college_id),check(ends_at>starts_at));
create table public.rsvps(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,event_id uuid not null,status text not null default 'going' check(status in ('going','cancelled')),checked_in_at timestamptz,unique(owner_id,event_id),foreign key(event_id,college_id) references events(id,college_id) on delete cascade);
create table public.listings(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,kind text not null check(kind in ('marketplace','lost','found','roommate','project','travel','sports')),price_paise int check(price_paise>=0),image_path text,status text not null default 'open' check(status in ('open','claimed','sold')));
create table public.reports(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,target_id uuid not null,target_type text not null check(target_type in ('posts','comments','profiles','notes','reviews','events','listings')),reason text not null,status text not null default 'open' check(status in ('open','resolved','dismissed')));
create table public.blocks(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,target_id uuid not null,unique(owner_id,target_id),foreign key(target_id,college_id) references profiles(id,college_id) on delete cascade);
create table public.mutes(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,community_id uuid not null,unique(owner_id,community_id),foreign key(community_id,college_id) references communities(id,college_id) on delete cascade);
create table public.bookmarks(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,post_id uuid not null,unique(owner_id,post_id),foreign key(post_id,college_id) references posts(id,college_id) on delete cascade);
create table public.appeals(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,status text not null default 'open' check(status in ('open','accepted','rejected')));
create table public.notifications(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,type text not null,read_at timestamptz,link text);
create table public.notification_settings(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,replies boolean not null default true,mentions boolean not null default true,events boolean not null default true,announcements boolean not null default true,deadlines boolean not null default true,unique(owner_id));
create table public.push_tokens(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,token text not null,unique(owner_id,token));
create table public.organizations(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null default '',kind text not null check(kind in ('club','coaching','recruiter')),verified boolean not null default false);
create table public.sponsored_items(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,organization_id uuid not null,title text not null,body text not null,branches text[] not null default '{}',years int[] not null default '{}',impressions bigint not null default 0,clicks bigint not null default 0,foreign key(organization_id,college_id) references organizations(id,college_id));
create table public.placements(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,company text not null,eligibility text not null,deadline timestamptz not null,verified boolean not null default false,kind text not null default 'job' check(kind in ('job','internship','experience')));
create table public.mentorships(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,kind text not null check(kind in ('mentor','mentee','referral')),status text not null default 'open');
create table public.study_groups(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,subject text not null);
create table public.deadlines(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null default '',due_at timestamptz not null);
create table public.campus_info(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,body text not null,kind text not null check(kind in ('mess','bus','facility')));
create table public.news_feeds(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,url text not null check(url like 'https://%'));
create table public.news_items(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,title text not null,url text not null,source text not null,published_at timestamptz not null);
create table public.contact_requests(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,target_id uuid not null,listing_id uuid,body text not null,status text not null default 'pending',foreign key(target_id,college_id) references profiles(id,college_id),foreign key(listing_id,college_id) references listings(id,college_id));
create table public.privacy_requests(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,owner_id uuid not null,created_at timestamptz not null default now(),unique(id,college_id),foreign key(owner_id,college_id) references profiles(id,college_id) on delete cascade,kind text not null check(kind in ('delete','export')),status text not null default 'pending' check(status in ('pending','completed')),completed_at timestamptz);

create table public.best_answers(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,post_id uuid not null unique,comment_id uuid not null,created_at timestamptz not null default now(),foreign key(comment_id,post_id,college_id) references comments(id,post_id,college_id));
create table public.moderation_actions(id uuid primary key default gen_random_uuid(),college_id uuid not null references colleges,actor_id uuid references profiles,action text not null,target_id uuid not null,reason text not null,created_at timestamptz not null default now());
create table private.rate_events(user_id uuid not null,kind text not null,created_at timestamptz not null default now());
create index rate_window on private.rate_events(user_id,kind,created_at);
create function private.rate_limit(k text,n int) returns void language plpgsql security definer set search_path='' as $$begin
perform pg_advisory_xact_lock(hashtext(auth.uid()::text||k));
if (select count(*) from private.rate_events where user_id=auth.uid() and kind=k and created_at>now()-interval '1 minute')>=n then raise exception 'Rate limit exceeded. Try again later.';end if;
insert into private.rate_events(user_id,kind) values(auth.uid(),k);end$$;
create function private.guard_write() returns trigger language plpgsql security definer set search_path='' as $$begin
if not private.active() then raise exception 'Consent required or account restricted';end if;
if tg_op='UPDATE' and (new.college_id<>old.college_id or new.owner_id<>old.owner_id or new.created_at<>old.created_at) then raise exception 'Identity fields are immutable';end if;
if tg_table_name='comments' then perform private.rate_limit('comment',10);end if;
return new;end$$;
alter table colleges enable row level security;
create policy college_read on colleges for select to authenticated using(id=private.college());
alter table profiles enable row level security;
create policy profile_read on profiles for select to authenticated using(college_id=private.college());
alter table sanctions enable row level security;
create policy sanction_read on sanctions for select to authenticated using(college_id=private.college() and (user_id=auth.uid() or private.staff()));
create function private.blocked_author(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from private.post_authors a join public.blocks b on b.target_id=a.user_id where a.post_id=pid and b.owner_id=auth.uid())$$;
alter table posts enable row level security;
create policy post_read on posts for select to authenticated using(college_id=private.college() and deleted_at is null and not exists(select 1 from public.mutes m where m.owner_id=auth.uid() and m.community_id=posts.community_id) and not private.blocked_author(id));
alter table communities enable row level security;
create policy tenant_read on communities for select to authenticated using(college_id=private.college());
create policy owner_insert on communities for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on communities for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on communities for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
create trigger guard_write before insert or update on communities for each row execute function private.guard_write();
alter table memberships enable row level security;
create policy tenant_read on memberships for select to authenticated using(college_id=private.college());
create policy owner_insert on memberships for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on memberships for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on memberships for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
create trigger guard_write before insert or update on memberships for each row execute function private.guard_write();
alter table comments enable row level security;
create policy tenant_read on comments for select to authenticated using(college_id=private.college());
create policy owner_insert on comments for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on comments for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on comments for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
create trigger guard_write before insert or update on comments for each row execute function private.guard_write();
alter table votes enable row level security;
create policy tenant_read on votes for select to authenticated using(college_id=private.college() and owner_id=auth.uid());
alter table polls enable row level security;
create policy tenant_read on polls for select to authenticated using(college_id=private.college());
alter table poll_responses enable row level security;
create policy tenant_read on poll_responses for select to authenticated using(college_id=private.college());
alter table notes enable row level security;
create policy tenant_read on notes for select to authenticated using(college_id=private.college());
create policy owner_insert on notes for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on notes for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on notes for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
create trigger guard_write before insert or update on notes for each row execute function private.guard_write();
alter table reviews enable row level security;
create policy tenant_read on reviews for select to authenticated using(college_id=private.college() and (approved or owner_id=auth.uid() or private.staff()));
create policy owner_insert on reviews for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on reviews for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on reviews for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
create trigger guard_write before insert or update on reviews for each row execute function private.guard_write();
alter table clubs enable row level security;
create policy tenant_read on clubs for select to authenticated using(college_id=private.college());
create policy owner_insert on clubs for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on clubs for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on clubs for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
