alter table events enable row level security;
create policy tenant_read on events for select to authenticated using(college_id=private.college());
create policy owner_insert on events for insert to authenticated with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_update on events for update to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active()) with check(college_id=private.college() and owner_id=auth.uid() and private.active());
create policy owner_delete on events for delete to authenticated using(college_id=private.college() and owner_id=auth.uid() and private.active());
create trigger guard_write before insert or update on events for each row execute function private.guard_write();
alter table rsvps enable row level security;
