alter table private.post_authors enable row level security;
alter table private.rate_events enable row level security;
create function public.create_post(input jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare pid uuid;cid uuid:=private.college();begin
if not private.active() then raise exception 'Consent required or account restricted';end if;
perform private.rate_limit('post',3);
if exists(select 1 from public.colleges c,unnest(c.keyword_filters) k where c.id=cid and k<>'' and lower(input->>'body') like '%'||lower(k)||'%') then raise exception 'Content violates college keyword rules';end if;
insert into public.posts(college_id,community_id,title,body,flair,anonymous) values(cid,(input->>'community_id')::uuid,input->>'title',regexp_replace(input->>'body','<[^>]*>','','g'),input->>'flair',coalesce((input->>'anonymous')::boolean,false)) returning id into pid;
insert into private.post_authors values(pid,auth.uid());return pid;end$$;
create function public.post_author(pid uuid) returns table(display_name text,badge text) language sql stable security definer set search_path='' as $$select case when p.anonymous then 'Anonymous' else pr.display_name end,case when p.anonymous then 'Verified Student' when pr.role='student' then 'Verified Student' else initcap(pr.role) end from public.posts p join private.post_authors pa on pa.post_id=p.id join public.profiles pr on pr.id=pa.user_id where p.id=pid and p.college_id=private.college()$$;
create function public.edit_post(pid uuid,new_body text) returns void language plpgsql security definer set search_path='' as $$begin
if not private.active() or not exists(select 1 from private.post_authors where post_id=pid and user_id=auth.uid()) then raise exception 'Not allowed';end if;
update public.posts set body=regexp_replace(new_body,'<[^>]*>','','g') where id=pid and college_id=private.college();end$$;
create function public.delete_post(pid uuid) returns void language plpgsql security definer set search_path='' as $$begin
if not exists(select 1 from private.post_authors where post_id=pid and user_id=auth.uid()) then raise exception 'Not allowed';end if;
update public.posts set deleted_at=now() where id=pid and college_id=private.college();end$$;
create function public.vote(pid uuid,direction int) returns void language plpgsql security definer set search_path='' as $$declare cid uuid:=private.college();begin
if not private.active() then raise exception 'Account restricted';end if;
perform private.rate_limit('vote',20);
if direction=-1 and not exists(select 1 from public.colleges where id=cid and downvotes_enabled) then raise exception 'Downvotes disabled';end if;
if direction not in (-1,1) then raise exception 'Invalid direction';end if;
insert into public.votes(college_id,owner_id,post_id,value) values(cid,auth.uid(),pid,direction) on conflict(owner_id,post_id) do update set value=excluded.value;
update public.posts set score=(select count(*) from public.votes where post_id=pid and value=1) where id=pid and college_id=cid;end$$;
create function public.accept_answer(pid uuid,cid uuid) returns void language plpgsql security definer set search_path='' as $$begin
if not exists(select 1 from private.post_authors where post_id=pid and user_id=auth.uid()) then raise exception 'Only author can accept';end if;
if not exists(select 1 from public.posts where id=pid and flair='Doubt' and college_id=private.college()) then raise exception 'Not a doubt';end if;
insert into public.best_answers(college_id,post_id,comment_id) values(private.college(),pid,cid);
update public.profiles set reputation=reputation+10 where id=(select owner_id from public.comments where id=cid);end$$;
create function public.moderate_target(target uuid,kind text,reason text) returns uuid language plpgsql security definer set search_path='' as $$declare author uuid;begin
if not private.staff() then raise exception 'Moderator required';end if;
if length(trim(reason))<5 then raise exception 'Reason required';end if;
if kind='reveal' then select a.user_id into author from private.post_authors a join public.posts p on p.id=a.post_id where a.post_id=target and p.college_id=private.college();
elsif kind in ('warn','mute','ban') then
 if not exists(select 1 from public.profiles where id=target and college_id=private.college()) then raise exception 'Wrong college';end if;
 insert into public.sanctions(college_id,user_id,kind,reason,expires_at) values(private.college(),target,kind,reason,case when kind='mute' then now()+interval '1 day' else null end);
elsif kind in ('remove','restore') then update public.posts set deleted_at=case when kind='remove' then now() else null end where id=target and college_id=private.college();
elsif kind='resolve_report' then update public.reports set status='resolved' where id=target and college_id=private.college();
else raise exception 'Unknown action';end if;
insert into public.moderation_actions(college_id,actor_id,action,target_id,reason) values(private.college(),auth.uid(),kind,target,reason);return author;end$$;
create function public.set_preferences(input jsonb) returns void language plpgsql security definer set search_path='' as $$begin update public.profiles set settings=input, sponsor_consent=coalesce((input->>'sponsor_consent')::boolean,false) where id=auth.uid();end$$;
create function public.export_my_data() returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin
select jsonb_build_object('profile',to_jsonb(p),'posts',(select coalesce(jsonb_agg(to_jsonb(po)),'[]') from public.posts po join private.post_authors a on a.post_id=po.id where a.user_id=auth.uid()),'comments',(select coalesce(jsonb_agg(to_jsonb(c)),'[]') from public.comments c where c.owner_id=auth.uid())) into result from public.profiles p where p.id=auth.uid();return result;end$$;
create function public.request_account_deletion() returns void language plpgsql security definer set search_path='' as $$begin insert into public.privacy_requests(college_id,owner_id,kind) values(private.college(),auth.uid(),'delete');end$$;
-- Grant RPCs explicitly; anonymous users can only look up an allowlisted college.
revoke all on all functions in schema public from public,anon;
grant execute on function public.allowed_college(text) to anon,authenticated;
grant execute on function public.update_my_profile(jsonb),public.create_post(jsonb),public.post_author(uuid),public.edit_post(uuid,text),public.delete_post(uuid),public.vote(uuid,int),public.accept_answer(uuid,uuid),public.moderate_target(uuid,text,text),public.set_preferences(jsonb),public.export_my_data(),public.request_account_deletion() to authenticated;
grant usage on schema private to authenticated;
grant execute on function private.college(),private.staff(),private.admin(),private.active(),private.blocked_author(uuid) to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
-- RLS is enabled on every table; lack of a policy denies access.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('campus-private','campus-private',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']);
create policy file_read on storage.objects for select to authenticated using(bucket_id='campus-private' and (storage.foldername(name))[1]=private.college()::text);
create policy file_write on storage.objects for insert to authenticated with check(bucket_id='campus-private' and (storage.foldername(name))[1]=private.college()::text and (storage.foldername(name))[2]=auth.uid()::text and private.active());
create policy file_delete on storage.objects for delete to authenticated using(bucket_id='campus-private' and (storage.foldername(name))[1]=private.college()::text and (storage.foldername(name))[2]=auth.uid()::text);
